// Validates and gates every write. Writes need SUNSYNK_WRITES_ENABLED=true AND dry_run=false in the request.
const b = $('Webhook').first().json.body || {};
const writesEnabled = String($env.SUNSYNK_WRITES_ENABLED || 'false').toLowerCase() === 'true';
const sn = String(b.sn || $env.SUNSYNK_INVERTER_SN || '');
if (!/^\d{6,12}$/.test(sn)) throw new Error('Missing or invalid inverter serial (sn)');
const allowed = {
  set_sell_time: /^sellTime[1-6]$/,
  set_grid_charge: /^time[1-6](On|on)$/,
  set_charge_cap: /^cap[1-6]$/,
  set_sell_enable: /^sellTime[1-6]En$/,
};
const re = allowed[b.command];
if (!re) throw new Error('Unknown command: ' + b.command);
const params = b.params || {};
for (const [k, v] of Object.entries(params)) {
  if (!re.test(k)) throw new Error(`Field ${k} not allowed for ${b.command}`);
  if (/^sellTime[1-6]$/.test(k) && !/^([01]\d|2[0-3]):[0-5]\d$/.test(String(v))) throw new Error(`${k} must be HH:MM`);
  if (/^cap[1-6]$/.test(k) && !(Number(v) >= 10 && Number(v) <= 100)) throw new Error(`${k} must be 10-100`);
}
const dryRun = b.dry_run !== false || !writesEnabled;
return [{ json: { sn, command: b.command, params, dry_run: dryRun, writes_enabled: writesEnabled } }];

// Sunsynk cloud login. Credentials come ONLY from n8n environment variables.
const crypto = require('crypto');
const host = $env.SUNSYNK_API_HOST || 'api.sunsynk.net';
const username = $env.SUNSYNK_USERNAME;
const password = $env.SUNSYNK_PASSWORD;
if (!username || !password) throw new Error('Set SUNSYNK_USERNAME and SUNSYNK_PASSWORD as n8n environment variables');
const state = $getWorkflowStaticData('global');
const now = Date.now();
if (state.bearer && state.expiry && now < state.expiry) return [{ json: { bearer: state.bearer, host } }];
const md5 = (s) => crypto.createHash('md5').update(s).digest('hex');
const nonce = now;
const pk = await this.helpers.httpRequest({ url: `https://${host}/anonymous/publicKey?nonce=${nonce}&source=sunsynk&sign=${md5(`nonce=${nonce}&source=sunsynkPOWER_VIEW`)}`, json: true });
if (!pk || !pk.success || !pk.data) throw new Error('Sunsynk public key request failed');
const pem = `-----BEGIN PUBLIC KEY-----\n${pk.data.match(/.{1,64}/g).join('\n')}\n-----END PUBLIC KEY-----\n`;
const enc = crypto.publicEncrypt({ key: pem, padding: crypto.constants.RSA_PKCS1_PADDING }, Buffer.from(password, 'utf8')).toString('base64');
const n2 = Date.now();
const login = await this.helpers.httpRequest({ method: 'POST', url: `https://${host}/oauth/token/new`, json: true,
  body: { areaCode: 'sunsynk', client_id: 'csp-web', grant_type: 'password', password: enc, source: 'sunsynk', username, nonce: n2, sign: md5(`nonce=${n2}&source=sunsynk${pk.data.substring(0, 10)}`) } });
if (!login || !login.success || !login.data || !login.data.access_token) throw new Error('Sunsynk login failed (MFA accounts are not supported)');
state.bearer = login.data.access_token;
state.expiry = now + login.data.expires_in * 1000 - 60000;
return [{ json: { bearer: state.bearer, host } }];

// Writes one settings change, then reads back and compares. Skipped entirely in dry run.
const v = $('Validate Request').first().json;
const { bearer, host } = $('Sunsynk Login').first().json;
if (v.dry_run) return [{ json: { ok: true, dry_run: true, would_write: v.params, command: v.command } }];
const headers = { Authorization: `Bearer ${bearer}` };
const set = await this.helpers.httpRequest({ method: 'POST', url: `https://${host}/api/v1/common/setting/${v.sn}/set`, headers, body: v.params, json: true });
const read = await this.helpers.httpRequest({ url: `https://${host}/api/v1/common/setting/${v.sn}/read`, headers, json: true });
const now = (read && read.data) || {};
// Some firmware accepts a write ("success") but ignores it. Trust the read-back, not the reply.
const mismatches = Object.entries(v.params).filter(([k, want]) => {
  const keys = [k, k.replace(/On$/, 'on'), k.replace(/on$/, 'On')];
  const got = keys.map((x) => now[x]).find((x) => x !== undefined);
  return String(got) !== String(want) && !(String(want) === '1' && String(got) === 'true') && !(String(want) === '0' && String(got) === 'false');
}).map(([k]) => k);
return [{ json: { ok: mismatches.length === 0, dry_run: false, command: v.command, set_reply_success: Boolean(set && set.success), mismatches } }];
